<script module lang="ts">
/**
 * CommentThread.Comment: one comment: its author, time, body, labels, actions and replies.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/comment-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext, type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/comment-thread.module.css'

export interface CommentThreadCommentProps {
  /**
   * The app's controls for this comment: ghost neutral sm Buttons, or a Menu.
   */
  actions?: Snippet
  /**
   * The author's name, drawn first. With the time it names the comment's article.
   */
  author: string
  /**
   * An Avatar with the author's name, drawn in a column one md Avatar wide.
   */
  avatar?: Snippet
  /**
   * The body: Text, Markdown or the app's own nodes, and a row of AttachmentChips.
   */
  children?: Snippet
  /**
   * The comment was changed after it was posted: the head says so after the time.
   */
  edited?: boolean
  /**
   * Labels after the head's words: Badges such as "Internal note" or "Resolved".
   */
  meta?: Snippet
  /**
   * The replies, as `CommentThread.Comment`s, drawn indented under the comment.
   */
  replies?: Snippet
  /**
   * When it was written: a RelativeTime, or text the app has formatted.
   */
  time?: Snippet
}
</script>

<script lang="ts">
let {
  actions,
  author,
  avatar,
  children,
  edited = false,
  meta,
  replies,
  time,
}: CommentThreadCommentProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
const owner: Record<string, any> = getContext('polymorph:CommentThread') ?? {}
const slots = {
  get actions() {
    return actions
  },
  get avatar() {
    return avatar
  },
  get default() {
    return children
  },
  get meta() {
    return meta
  },
  get replies() {
    return replies
  },
  get time() {
    return time
  },
}
const words = $derived(owner.messages ?? { edited: 'Edited', replies: 'Replies' })
const authorId = $derived(`${uid}-author`)
const timeId = $derived(`${uid}-time`)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<li class={styles.comment}
    ><article class={styles.entry} aria-labelledby={slots.time ? `${authorId} ${timeId}` : authorId}
      >{#if slots.avatar}<span class={styles.mark}>{@render avatar?.()}</span>{/if
      }<div class={styles.body}
        ><div class={styles.head}
          ><span class={styles.author} id={authorId}>{author}</span
          >{#if slots.time}<span class={styles.time} id={timeId}>{@render time?.()}</span>{/if
          }{#if edited}<span class={styles.edited}>{words.edited}</span>{/if
          }{#if slots.meta}<span class={styles.meta}>{@render meta?.()}</span>{/if
        }</div
        ><div class={styles.content}>{@render children?.()}</div
        >{#if slots.actions}<div class={styles.actions}>{@render actions?.()}</div>{/if
      }</div
    ></article
    >{#if slots.replies
      }<ol class={styles.replies} role="list" aria-label={words.replies}>{@render replies?.()}</ol
    >{/if
  }</li
>{/if
}{@render joined.end?.()}
